const FIXTURE = {
  competiciones: COMPETICIONES,
  equipos: EQUIPOS,
  grupos: {
    A: ['flu', 'ccp', 'ali_lim', 'col_chi'],
    B: ['sao', 'bsc', 'tal', 'cob'],
    C: ['gre', 'elp', 'the_str', 'huac'],
    D: ['ldu', 'jun', 'uni_per', 'bot'],
    E: ['fla', 'bol', 'mfc', 'pal_chi'],
    F: ['pal', 'idv', 'slo', 'liv_uru'],
    G: ['pen', 'cam', 'cen', 'car_fc'],
    H: ['riv', 'nac_uru', 'lib_par', 'tac']
  },
  gruposLibertadores: {
    A: ['flu', 'ccp', 'ali_lim', 'col_chi'],
    B: ['sao', 'bsc', 'tal', 'cob'],
    C: ['gre', 'elp', 'the_str', 'huac'],
    D: ['ldu', 'jun', 'uni_per', 'bot'],
    E: ['fla', 'bol', 'mfc', 'pal_chi'],
    F: ['pal', 'idv', 'slo', 'liv_uru'],
    G: ['pen', 'cam', 'cen', 'car_fc'],
    H: ['riv', 'nac_uru', 'lib_par', 'tac']
  },
  gruposSudamericana: {
    A: ['dyj', 'dim', 'ucv_per', 'car'],
    B: ['cru', 'calera', 'ucat_ecu', 'ali'],
    C: ['inter_rs', 'delf', 'bel', 'tom'],
    D: ['cabj', 'cruz', 'npo', 'trin'],
    E: ['cap', 'dan', 'ame_par', 'ray_zul'],
    F: ['cor', 'arg_jrs', 'rac_mvd', 'nac_par'],
    G: ['lan', 'cui', 'dgar', 'met'],
    H: ['rac', 'bra', 'coq', 'luq']
  },
  partidos: PARTIDOS,
  resultadosIniciales: RESULTADOS_INICIALES,

  /* Retorna datos del equipo con escudo adaptable (imagen con fallback) */
  equipo(c) {
    const e = EQUIPOS[c];
    if (!e) return { n: c || 'Por definir', b: '⚽', g: '', comp: '' };
    
    const src = e.escudo || (typeof e.b === 'string' && (e.b.includes('/') || e.b.endsWith('.png') || e.b.endsWith('.svg')) ? e.b : null);
    const b = src 
      ? `<img src="${src}" class="escudo-img" alt="${e.n}" data-equipo="${c}" title="Ver perfil de ${e.n}" loading="lazy" onerror="this.onerror=null;this.outerHTML='⚽'">`
      : (e.b || '⚽');

    return { ...e, b, escudoSrc: src, code: c };
  },

  porId(id) {
    return this.partidos.find(p => p.id === id);
  },

  porCompeticion(compId) {
    return this.partidos.filter(p => p.competicion === compId);
  },

  porFecha(jornada) {
    return this.partidos.filter(p => p.jornada === Number(jornada));
  }
};

if (typeof window !== 'undefined') window.FIXTURE = FIXTURE;
export { FIXTURE };